import {pauseRunClock,resumeRunClock} from './run-clock.js?v=finish-14';
import {practicePreferences,missedQuestions} from './practice-flow.js?v=practice-13';
import {briefFeedback} from './feedback.js?v=unified-12';
import {groupsFor,ALL_GROUPS,LEVELS,levelOf,isNewSkill,groupFor,newLesson,notation,optionMarkup} from './course.js?v=unified-12';
import {note,interval,INTERVALS,SKILLS,staff,pitchName,explanation,makeQuestion,shuffle,inversion} from './course.js?v=unified-12';
import {createProgress} from './progress.js?v=middle-1';
import {Piano} from './piano.js?v=unified-12';
const STORE='jianle-interval-v2';let initial={};try{initial=JSON.parse(localStorage.getItem(STORE)||'{}')}catch{}
const db=createProgress(initial);
const preferences=practicePreferences(db.settings.practice);let practiceOptionsOpen=false;
let GROUPS=groupsFor(db.level),recordFilter='all',wrongReturn='mine';
const app=document.querySelector('#app');let group='sound',view='home',skill='names',difficulty=preferences.difficulty,mode=preferences.intervalMode,count=preferences.count,quiz=null,result=null,showMap=false;
group=GROUPS[0].id;skill=GROUPS[0].skills[0];
let highlightFrame=0,highlightedNotes=[];
let audioStatus='ready',audioMessage='';
const openChapters={primary:null,intermediate:null};
const piano=new Piano((status,message)=>{audioStatus=status;audioMessage=message||'';updateAudio()});piano.volume=db.settings.volume;piano.duration=db.settings.duration;
function questionForButton(el){return el.dataset.index!==undefined?result?.questions[Number(el.dataset.index)]:quiz?.questions[quiz.index]}
function sequenceNotes(seq){return [...new Set([48,...seq.flatMap(e=>e.notes)])]}
function notesForButton(el){
 if(el.dataset.sequence)return sequenceNotes(JSON.parse(decodeURIComponent(el.dataset.sequence)));
 const q=questionForButton(el);if(el.dataset.act!=='demo'&&q?.sequence)return sequenceNotes(q.sequence);
 if(el.dataset.act==='demo')return el.dataset.notes.split(',').map(Number);
 if(['play-q','chord-arpeggio','answer-audio'].includes(el.dataset.act))return q?.notes.map(n=>n.midi)||[];
 if(el.dataset.act==='review-audio')return result?.questions[Number(el.dataset.index)]?.notes.map(n=>n.midi)||[];
 return [];
}
function updateAudio(){
 if(!piano.playing)clearNoteHighlight();
 let preparing=false,failed=false;
 document.querySelectorAll('[data-act="demo"],[data-act="play-q"],[data-act="review-audio"],[data-act="chord-arpeggio"],[data-act="answer-audio"]').forEach(el=>{
  const notes=notesForButton(el),ready=piano.ready(notes),error=piano.failed(notes);
  el.disabled=!ready&&!error;el.setAttribute('aria-busy',!ready&&!error?'true':'false');
  if(!ready&&!error)preparing=true;if(error)failed=true;
  el.title=ready?'钢琴已准备好，点击即播放':error?'采样未加载成功，点击重试':'正在提前准备钢琴采样';
 });
 document.querySelectorAll('[data-audio-status]').forEach(el=>{el.hidden=!(audioStatus==='playing'||failed||preparing);el.textContent=audioStatus==='playing'?'播放中':failed?'加载失败，请重试':preparing?'准备中…':''});
 document.querySelectorAll('.waveform').forEach(el=>el.classList.toggle('is-playing',audioStatus==='playing'));
 if(audioStatus==='error')toast(audioMessage||'无法加载音频，请重试');
}
function clearNoteHighlight(){cancelAnimationFrame(highlightFrame);highlightFrame=0;highlightedNotes.forEach(n=>n.classList.remove('is-playing','is-resting'));highlightedNotes=[]}
function highlightPlayback(el,q=null){
 if(!el)return;
 clearNoteHighlight();
 const scope=el.closest('.q-card')||el.closest('.card')||el.closest('.view-lesson');if(!scope)return;
 const hasOptions=q?.optionScores||q?.optionRhythms;
 const notes=[...scope.querySelectorAll(hasOptions?'.option.correct .score-note,.answer-detail .score-note':'.score-note')];
 const events=[...scope.querySelectorAll(hasOptions?'.option.correct .rhythm-event,.answer-detail .rhythm-event':'.rhythm-event')];
 if(!notes.length&&!events.length)return;
 const token=piano.serial;highlightedNotes=[...notes,...events];
 const paint=()=>{if(!scope.isConnected||token!==piano.serial||!piano.playing){clearNoteHighlight();return}
  const active=piano.activeNoteIndices();
  notes.forEach(n=>{const i=Number(n.dataset.noteIndex);n.classList.toggle('is-playing',active.includes(i)&&Number(n.dataset.midi)===piano.visual?.notes?.[i])});
  const activeEvents=piano.activeEventIndices();
  events.forEach(n=>{const e=activeEvents.find(e=>e.index===Number(n.dataset.eventIndex));n.classList.toggle('is-playing',!!e&&!e.rest);n.classList.toggle('is-resting',!!e&&e.rest)});
  highlightFrame=requestAnimationFrame(paint);
 };paint();
}
function playQuestion(q,modeOverride,el){const played=q.sequence?piano.playSequence(q.sequence,db.settings.bpm||80,2):piano.play(q.notes.map(n=>n.midi),modeOverride||q.mode);if(played)highlightPlayback(el,q);return played}

function answerAudio(q,index=null){
 if(!q.notes.length)return '';
 const target=index===null?'':` data-index="${index}"`;
 const controls=q.chord?[['harmonic','同时听'],['up','逐音听']]:[['',q.sequence?'重听节奏':'整段重听']];
 return `<div class="answer-audio" role="group" aria-label="答案音频对照">${controls.map(([mode,text])=>`<button class="secondary" data-act="answer-audio" data-mode="${mode}"${target}>${icon('play')}${text}</button>`).join('')}</div><p class="audio-state" data-audio-status aria-live="polite"></p>`;
}
function audioControls(){return `<div class="rhythm-controls"><span>2拍预备</span><label>速度 <select aria-label="节奏播放速度" data-setting="bpm">${[60,70,80,90,100,120].map(v=>`<option value="${v}" ${(db.settings.bpm||80)===v?'selected':''}>${v} BPM</option>`).join('')}</select></label></div>`}
function prepareScreenAudio(){
 const notes=[...document.querySelectorAll('[data-act="demo"],[data-act="play-q"],[data-act="review-audio"],[data-act="chord-arpeggio"],[data-act="answer-audio"]')].flatMap(notesForButton);
 if(quiz&&!quiz.finished){for(const q of quiz.questions.slice(quiz.index,quiz.index+3))notes.push(...q.notes.map(n=>n.midi))}
 if(notes.length)piano.prepare(notes).catch(()=>{});
 updateAudio();
}

function save(){try{localStorage.setItem(STORE,JSON.stringify(db))}catch{toast('本机记录未能保存，请检查浏览器存储设置')}}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',2800)}
