const icon=(name,cls='',filled=false)=>`<svg class="ui-icon ${cls}" width="24" height="24" viewBox="0 0 24 24" fill="currentColor" stroke="none" aria-hidden="true" focusable="false">${ICONS[filled?name+'_filled':name]||ICONS[name]||ICONS.notation}</svg>`;
const nav=()=>`<nav class="nav" aria-label="主导航">${[['home','学习','home'],['practice','练习','practice'],['mine','我的','person']].map(([id,t,ic])=>`<button data-act="go" data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}><span class="nav-indicator">${icon(ic,'',view===id)}</span><span class="nav-label">${t}</span></button>`).join('')}</nav>`;
const levelTitle=()=>LEVELS.find(l=>l.id===db.level).title;
const levelSwitch=()=>`<div class="level-switch" role="group" aria-label="学习级别">${LEVELS.map(l=>`<button data-act="level" data-level="${l.id}" class="${db.level===l.id?'active':''}" aria-pressed="${db.level===l.id}">${l.label}</button>`).join('')}</div>`;
const scopedWrong=()=>db.wrong.filter(q=>recordFilter==='all'||levelOf(q.skill)===recordFilter);
const recordChips=()=>`<div class="record-filters chips" role="group" aria-label="记录级别">${[['all','全部'],...LEVELS.map(l=>[l.id,l.title])].map(([id,t])=>`<button class="chip ${recordFilter===id?'active':''}" data-act="record-filter" data-filter="${id}" aria-pressed="${recordFilter===id}">${t}</button>`).join('')}</div>`;
const skillInfo=id=>SKILLS.find(x=>x.id===id);
const backHead=(title,action='go',to='home')=>`<header class="back-head"><button class="icon-button back" data-act="${action}" data-view="${to}" aria-label="返回">${icon('back')}</button><h2>${title}</h2><span class="appbar-space"></span></header>`;
function go(next){piano.stop();view=next;render();window.scrollTo(0,0)}
function statsFor(id){const a=db.attempts.filter(x=>!id||x.skill===id).slice(-20);return{n:a.length,accuracy:a.length?Math.round(a.filter(x=>x.correct).length/a.length*100):0}}
function skillCard(s){const a=statsFor(s.id);return `<button class="skill-card" data-act="lesson" data-skill="${s.id}"><span class="row-icon">${icon(groupFor(s.id).icon&&s.id.startsWith('b-')?groupFor(s.id).icon:groupFor(s.id).id)}</span><div class="row-copy"><h3>${s.title}</h3>${a.n?`<span class="tiny">最近正确率 ${a.accuracy}%</span>`:''}</div>${icon('chevron','row-chevron')}</button>`}
function home(){
 const next=skillInfo(nextSkill()),active=db.active;
 const current=active?.questions[active.index]?.skill||next.id,currentGroup=groupFor(current);
 const done=active?Object.values(active.answers).filter(x=>x.checked).length:currentGroup.skills.filter(id=>db.completedLessons.includes(id)).length;
 const total=active?active.questions.length:currentGroup.skills.length;
 const openGroup=openChapters[db.level]===null?currentGroup.id:openChapters[db.level];
 return `<div class="page-heading"><h1 class="page-title">学习</h1>${levelSwitch()}</div>
 <section class="continue-card" aria-label="${active?'继续学习':'推荐学习'}">
  <div class="continue-copy"><div class="continue-kicker">${active?'继续学习':currentGroup.title}</div><h2>${active?active.label:next.title}</h2><div class="continue-meta">${done} / ${total}${active?' 题':' 项已练'}</div></div>
  <button class="primary" data-act="${active?'resume':'lesson'}" ${!active?`data-skill="${next.id}"`:''}>${active?'继续学习':'开始学习'}</button>
  <div class="continue-progress module-progress" role="progressbar" aria-label="${active?'本次练习进度':'本章已练专项'}" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${done}"><i style="width:${done/total*100}%"></i></div>
 </section>
 <div class="section-head"><h2>学习内容</h2></div><div class="chapter-list">${GROUPS.map(g=>{
  const done=g.skills.filter(id=>db.completedLessons.includes(id)).length;
  return `<details class="chapter" data-chapter="${g.id}" ${g.id===openGroup?'open':''}>
   <summary><div class="chapter-heading"><h3>${g.title}</h3><div class="module-progress" role="progressbar" aria-label="${g.title}已练专项" aria-valuemin="0" aria-valuemax="${g.skills.length}" aria-valuenow="${done}"><i style="width:${done/g.skills.length*100}%"></i></div></div>${icon('chevron','chapter-chevron')}</summary>
   <div class="chapter-lessons">${g.skills.map(id=>{const currentItem=id===current;return `<button class="chapter-lesson ${currentItem?'current':''}" data-act="lesson" data-skill="${id}" ${currentItem?'aria-current="step"':''}><span>${skillInfo(id).title}</span>${db.completedLessons.includes(id)?icon('check','lesson-check'):''}</button>`}).join('')}<button class="chapter-overview" data-act="module" data-group="${g.id}">本章练习</button></div>
  </details>`;
 }).join('')}</div>`;
}
function modulePage(){const g=ALL_GROUPS.find(x=>x.id===group);return `${backHead(g.title)}<div class="skill-grid">${g.skills.map(id=>skillCard(skillInfo(id))).join('')}</div><div class="bottom-actions"><button class="secondary" data-act="group-practice" data-group="${group}">专项练习</button><button class="primary" data-act="module-mixed" data-group="${group}">综合练习 · 10题</button></div>`}
function nextSkill(){return SKILLS.find(x=>levelOf(x.id)===db.level&&!db.completedLessons.includes(x.id))?.id||GROUPS[0].skills[0]}
function example(spec,root=note(28),opts={}){return staff(interval(root,spec),{label:true,highlight:true,...opts})}
function lesson(){const s=skillInfo(skill);if(isNewSkill(skill))return `${backHead(s.title,'go','module')}${skill.startsWith('b-')&&['b-rhythm','b-triplets'].includes(groupFor(skill).id)?audioControls():''}${newLesson(skill).replaceAll('▶ ',icon('play')+' ')}<p class="audio-state" data-audio-status aria-live="polite"></p><div class="bottom-actions"><button class="secondary" data-act="module" data-group="${groupFor(skill).id}">返回模块</button><button class="primary" data-act="configure" data-skill="${skill}">开始练习</button></div>`;let content='';if(skill==='steps')content=`<p class="lesson-text">钢琴上<strong>相邻的两个琴键</strong>（包含黑键）相距一个半音。两个半音组成一个全音。E—F、B—C 虽然都是相邻白键，但中间没有黑键，相距半音。</p><div class="compare"><div class="card"><h3>E—F · 半音</h3>${example(INTERVALS[1],note(30),{id:'step-half'})}<p>相距 1 个半音</p><button class="secondary" data-act="demo" data-notes="64,65">${icon('play')} 听半音</button></div><div class="card"><h3>C—D · 全音</h3>${example(INTERVALS[2],note(28),{id:'step-whole'})}<p>相距 2 个半音</p><button class="secondary" data-act="demo" data-notes="60,62">${icon('play')} 听全音</button></div></div><div class="rule">不要只数白键；相邻白键之间可能是全音，也可能是半音。</div>`;
else if(skill==='thirds')content=`<p class="lesson-text">先固定起音 C，比较 C—E♭ 和 C—E。它们都跨三个音名字母，都是三度；<strong>小三度含3个半音，大三度含4个半音。</strong></p><div class="compare"><div class="card"><h3>小三度</h3>${example(INTERVALS[3],note(28),{id:'third-small'})}<p>3个半音 · C—E♭</p><button class="secondary" data-act="demo" data-notes="60,63">${icon('play')} 听小三度</button></div><div class="card"><h3>大三度</h3>${example(INTERVALS[4],note(28),{id:'third-large'})}<p>4个半音 · C—E</p><button class="secondary" data-act="demo" data-notes="60,64">${icon('play')} 听大三度</button></div></div><div class="card"><h3>再听一次，比较距离</h3><p>交替播放“小三度 → 大三度”，关注第二个音相对起音的位置。</p><button class="secondary" data-act="demo" data-notes="60,63,60,64">${icon('play')} 连续对比</button></div><div class="rule">先练同一根音，分清后再换根音。不要仅凭“快乐／悲伤”判断，听清音高距离更可靠。</div>`;
else if(skill==='read')content=`<p class="lesson-text">判断音程要分两步：<strong>先数音名字母确定度数，再数半音判断性质。</strong>数度数时，起音和终音都包括在内。</p><div class="card">${example(INTERVALS[4],note(28),{id:'read-example'})}<h3>C—E：为什么是大三度？</h3><p>① C、D、E，共三个音名 → 三度。<br>② C—C♯—D—D♯—E，共四个半音 → 大三度。</p><button class="secondary" data-act="demo" data-notes="60,64">${icon('play')} 听这个音程</button></div><div class="rule">升降号改变半音距离，但不改变音名字母的数量。例如 C—E♭ 仍是三度，性质变为小三度。</div><div class="grid-lesson">${referenceCard('纯音程','纯一度 0 · 纯四度 5<br>纯五度 7 · 纯八度 12')}${referenceCard('大小音程','小／大二度 1／2 · 小／大三度 3／4<br>小／大六度 8／9 · 小／大七度 10／11')}</div><p class="tiny">表内数字为半音数。进阶练习会加入增四度与减五度；两者均为6个半音，写法不同。</p>`;
else if(skill==='ear')content=`<p class="lesson-text">先听熟纯四度和纯五度，再混合练二、三、六、七、八度。你可以选择<strong>上行、下行或同时发声</strong>，每次练习保持一种播放方式。</p><div class="compare"><div class="card"><h3>纯四度</h3>${example(INTERVALS[5],note(28),{id:'ear-fourth'})}<p>5个半音</p><button class="secondary" data-act="demo" data-notes="60,65">${icon('play')} 听纯四度</button></div><div class="card"><h3>纯五度</h3>${example(INTERVALS[8],note(28),{id:'ear-fifth'})}<p>7个半音</p><button class="secondary" data-act="demo" data-notes="60,67">${icon('play')} 听纯五度</button></div></div><div class="card"><h3>同时发声，也是一组音程</h3><p>旋律音程是先后发声，和声音程是同时发声。它们可以有相同的音高距离。</p><button class="secondary" data-act="demo" data-notes="60,67" data-mode="harmonic">${icon('play')} 听和声纯五度</button></div><div class="rule">听辨练习不包含增四度与减五度的二选一：十二平均律中，两者同为6个半音，仅靠声音不能确定谱面写法。</div>`;
else content=`<p class="lesson-text">把低音移高一个八度，或把高音移低一个八度，两个音的位置就互换了，这叫<strong>音程转位</strong>。</p><div class="compare"><div class="card"><h3>原音程 · 大三度</h3>${example(INTERVALS[4],note(28),{id:'invert-before'})}<p>C4—E4</p><button class="secondary" data-act="demo" data-notes="60,64">${icon('play')} 听原音程</button></div><div class="card"><h3>转位后 · 小六度</h3>${staff([note(30),note(35)],{label:true,id:'invert-after'})}<p>E4—C5</p><button class="secondary" data-act="demo" data-notes="64,72">${icon('play')} 听转位后</button></div></div><div class="rule">度数相加等于9：三度 ↔ 六度，四度 ↔ 五度。<br>性质：大 ↔ 小，增 ↔ 减，纯 ↔ 纯。<br>半音数相加等于12。</div><p class="tiny">本阶段转位练习使用二度至七度，先掌握最常见的单音程转位。</p>`;
return `${backHead(s.title)}${content}<p class="audio-state" data-audio-status aria-live="polite"></p><div class="bottom-actions"><button class="secondary" data-act="module" data-group="${groupFor(skill).id}">返回模块</button><button class="primary" data-act="configure" data-skill="${skill}">开始练习</button></div>`}
function referenceCard(t,c){return `<div class="card"><h3>${t}</h3><p>${c}</p></div>`}
function selectPracticeSkill(id){skill=id;mode=skill==='b-chord-ear'?preferences.chordMode:preferences.intervalMode}
function savePracticePreferences(){preferences.count=count;preferences.difficulty=difficulty;if(skill==='b-chord-ear')preferences.chordMode=mode;else if(['thirds','ear'].includes(skill))preferences.intervalMode=mode;db.settings.practice={...preferences};save()}
function configurationFields(){const ear=['thirds','ear','b-chord-ear'].includes(skill),chordEar=skill==='b-chord-ear';return `<div class="configuration"><div class="field"><label>难度</label><div class="chips">${[['basic',['thirds','b-chord-ear'].includes(skill)?'固定根音 C':'基础'],['varied',['thirds','b-chord-ear'].includes(skill)?'变化根音':'变化']].map(([id,t])=>`<button class="chip ${difficulty===id?'active':''}" aria-pressed="${difficulty===id}" data-act="difficulty" data-value="${id}">${t}</button>`).join('')}</div></div>${ear?`<div class="field"><label>听音方式</label><div class="chips">${(chordEar?[['harmonic','同时弹响'],['up','逐音弹奏']]:[['up','上行'],['down','下行'],['harmonic','和声']]).map(([id,t])=>`<button class="chip ${mode===id?'active':''}" aria-pressed="${mode===id}" data-act="mode" data-value="${id}">${t}</button>`).join('')}</div></div>`:''}<div class="field"><label>题量</label><div class="chips">${[5,10,15].map(n=>`<button class="chip ${count===n?'active':''}" aria-pressed="${count===n}" data-act="count" data-value="${n}">${n}题</button>`).join('')}</div></div></div>`}
function configure(){return `${backHead(skillInfo(skill).title,'go','practice')}${configurationFields()}<div class="bottom-actions"><button class="secondary" data-act="lesson" data-skill="${skill}">看讲解</button><button class="primary" data-act="start">开始练习</button></div>`}
function practice(){
 if(!GROUPS.some(g=>g.id===group))group=GROUPS[0].id;
 const g=GROUPS.find(x=>x.id===group);if(!g.skills.includes(skill))selectPracticeSkill(g.skills[0]);
 const active=db.active,answered=active?Object.values(active.answers).filter(a=>a.checked).length:0;
 const ear=['thirds','ear','b-chord-ear'].includes(skill);
 const summary=`${count}题 · ${difficulty==='basic'?'基础':'变化'}${ear?' · '+({up:skill==='b-chord-ear'?'逐音':'上行',down:'下行',harmonic:'同时听'})[mode]:''}`;
 return `<div class="page-heading"><h1 class="page-title">练习</h1>${levelSwitch()}</div>
 ${active?`<button class="practice-resume" data-act="resume"><span class="resume-play">${icon('play')}</span><span><b>继续上次练习</b><small>${active.label} · ${answered}/${active.questions.length}题</small></span>${icon('chevron','row-chevron')}</button>`:''}
 <div class="chips module-chips" role="group" aria-label="练习模块">${GROUPS.map(g=>`<button class="chip ${group===g.id?'active':''}" aria-pressed="${group===g.id}" data-act="practice-group" data-group="${g.id}">${g.title}</button>`).join('')}</div>
 <div class="practice-skills" role="group" aria-label="选择练习专项">${g.skills.map(id=>`<button class="practice-skill ${id===skill?'selected':''}" data-act="select-practice" data-skill="${id}" aria-pressed="${id===skill}"><span>${skillInfo(id).title}</span><span class="practice-radio" aria-hidden="true"></span></button>`).join('')}</div>
 <details class="practice-options" ${practiceOptionsOpen?'open':''}><summary><span>${summary}</span><span class="adjust-label">调整${icon('chevron')}</span></summary>${configurationFields()}</details>
 <button class="primary practice-start" data-act="start">开始练习</button>
 <div class="practice-extras"><button data-act="start-mixed">${icon('practice')}<span>综合练习</span><small>${db.level==='intermediate'?21:15}题</small></button><button data-act="practice-wrong">${icon('wrong')}<span>错题巩固</span><small>${db.wrong.filter(q=>levelOf(q.skill)===db.level).length}题</small></button></div>`;
}

function mine(){const a=statsFor();return `<h1 class="page-title mine-title">我的<span class="inline-brand">简乐</span></h1><section class="stats"><div><strong>${db.attempts.length}</strong><span class="tiny">已练题次</span></div><div><strong>${a.n?a.accuracy+'%':'—'}</strong><span class="tiny">最近正确率</span></div><div><strong>${db.wrong.length}</strong><span class="tiny">待复习</span></div></section><div class="menu-group">${menuRow('wrong','我的错题','wrong',db.wrong.length)}${menuRow('history','学习记录','history')}</div><div class="menu-group">${menuRow('settings','声音设置','volume')}${menuRow('help','使用说明','help')}${menuRow('about','关于简乐','info')}</div>`}
function menuRow(to,title,ic,badge=0){return `<button class="menu-row" data-act="go" data-view="${to}"><span class="row-icon">${icon(ic)}</span><span class="row-copy">${title}</span>${badge?`<span class="count-badge">${badge}</span>`:''}${icon('chevron','row-chevron')}</button>`}
function settings(){return `${backHead('声音设置','go','mine')}<div class="settings"><div class="setting-line"><label for="volume">音量 <span class="tiny" id="volume-value">${Math.round(db.settings.volume*100)}%</span></label><input id="volume" type="range" min=".1" max="1" step=".05" value="${db.settings.volume}" data-setting="volume"></div><div class="setting-line"><label for="duration">单音时长</label><select id="duration" data-setting="duration">${[[.65,'短'],[.9,'适中'],[1.3,'长']].map(([v,t])=>`<option value="${v}" ${db.settings.duration===v?'selected':''}>${t}</option>`).join('')}</select></div><button class="secondary" data-act="demo" data-notes="60,64,67">${icon('play')} 试听钢琴</button><span class="tiny audio-state" data-audio-status aria-live="polite"></span></div>`}
function history(){const sessions=db.sessions.filter(s=>recordFilter==='all'||(s.level||'primary')===recordFilter);return `${backHead('学习记录','go','mine')}${recordChips()}${sessions.length?`<div class="history-list">${sessions.slice(-30).reverse().map(s=>`<div class="history-row"><div><b>${s.label}</b><div class="tiny">${new Date(s.date).toLocaleDateString('zh-CN')} · ${s.answered!==undefined&&s.answered<s.count?s.answered+'/'+s.count+'题已答':s.count+'题'} · ${(s.level||'primary')==='intermediate'?'中级':'初级'}</div></div><strong>${s.correct}/${s.answered??s.count}</strong></div>`).join('')}</div>`:'<div class="empty"><div class="empty-icon">'+icon('history')+'</div><h2>还没有完成的练习</h2></div>'}`}
function help(){return `${backHead('使用说明','go','mine')}<div class="help-content"><section><h3>怎么开始</h3><p>在“学习”里选知识点，先看例子，再开始练习。“练习”可以直接选择专项，或进行当前级别的综合练习。初级与中级可在页面顶部切换，不需要解锁。</p></section><section><h3>答题与错题</h3><p>选择答案后点击“检查答案”。答完可查看解析和对应讲解；点击顶部题号可跳题或结束练习。错题自动收集，重新答对后移出；也可以练同类新题。</p></section><section><h3>钢琴播放</h3><p>采样会提前准备，加载时播放按钮暂不可用。上行、下行是先后发声，和声是同时发声。音量和单音时长可在“声音设置”调整。中级节奏使用两拍预备，可单独调整播放速度；和弦可同时弹响或逐音对照。</p></section><section><h3>记录保存在哪里</h3><p>进度和错题保存在当前浏览器，可保存退出、刷新后继续。尚不支持跨设备同步，清除浏览器数据可能丢失记录。最近正确率按最近20次作答统计；练习用时不包含暂停、后台停留和查看讲解的时间。</p></section><section><h3>学习范围</h3><p>初级包含五个模块、17个专项；中级包含七个模块、18个专项，覆盖三和弦、小调、调内音级与和弦、三连音、节奏和术语。题目为按乐理规则生成的练习，不作为正式考级试卷。当前以辨认、听辨和选择题为主，构成和弦与小节线练习采用谱面选择，暂不支持自由手写谱面。</p></section></div>`}
function about(){return `${backHead('关于简乐','go','mine')}<div class="about-mark">♪</div><h1 class="about-title">简乐</h1><p class="about-subtitle">乐理学习与练习</p><div class="help-content"><section><h3>钢琴音源</h3><p>Salamander Grand Piano · Alexander Holm，<a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener">CC BY 3.0</a>。录音由 <a href="https://github.com/Tonejs/audio/tree/master/salamander" target="_blank" rel="noopener">Tone.js 音频仓库</a>分发。本应用按音高播放采样，并调整时值与音量。</p></section><section><h3>谱面字体</h3><p>Bravura · Steinberg Media Technologies，<a href="assets/fonts/LICENSE.txt" target="_blank">SIL Open Font License 1.1</a>。</p></section><section><h3>界面图标</h3><p>Material Symbols Rounded · Google，<a href="assets/icons/LICENSE.txt" target="_blank">Apache License 2.0</a>。调号与力度符号使用 Bravura。</p></section><section><h3>原卷练习</h3><p><a href="original/">打开旧版35题练习</a></p></section></div>`}
function wrong(){const filtered=scopedWrong();return `${backHead('我的错题','go',wrongReturn)}${recordChips()}${filtered.length?`<div class="section-head"><span class="tiny">${filtered.length}题</span></div><div class="bottom-actions"><button class="primary" data-act="start-wrong">重练错题</button><button class="secondary" data-act="reinforce-wrong">同类新题</button></div><div class="wrong-list">${filtered.map((q,i)=>`<button class="menu-row" data-act="wrong-one" data-index="${db.wrong.indexOf(q)}"><span class="row-icon">${icon(q.skill.startsWith('b-')?groupFor(q.skill).icon:groupFor(q.skill).id)}</span><div class="row-copy"><b>${skillInfo(q.skill).title}</b><span class="tiny">${q.title}</span></div>${icon('chevron','row-chevron')}</button>`).join('')}</div>`:`<div class="empty"><div class="empty-icon">${icon('check')}</div><h2>没有待复习的错题</h2><button class="secondary" data-act="go" data-view="practice">去练习</button></div>`}`}
function render(){clearNoteHighlight();let content=view==='home'?home():view==='module'?modulePage():view==='lesson'?lesson():view==='practice'?practice():view==='configure'?configure():view==='mine'?mine():view==='wrong'?wrong():view==='settings'?settings():view==='history'?history():view==='help'?help():view==='about'?about():view==='quiz'?questionPage():resultPage();const narrow=['module','lesson','configure','quiz','result','wrong','settings','history','help','about'].includes(view);app.innerHTML=`<main class="shell view-${view} ${narrow?'narrow':''}">${content}</main>${['home','practice','mine'].includes(view)?nav():''}`;prepareScreenAudio()}
function makeRun(questions,label,kind='practice',runDifficulty=difficulty){piano.stop();quiz={level:db.level,difficulty:runDifficulty,questions,answers:{},index:0,label,kind,elapsed:0,started:Date.now(),finished:false};view='quiz';showMap=false;saveActive();render();window.scrollTo(0,0)}
function replaceActive(fn){if(db.active){ask('开始新的练习？','上次未完成的进度将被替换，已答记录会保留。',fn)}else fn()}
function start(){replaceActive(()=>{const seed=Math.floor(Math.random()*1e9);makeRun(Array.from({length:count},(_,i)=>makeQuestion(skill,i,seed,difficulty,skill==='b-chord-ear'?(['harmonic','up'].includes(mode)?mode:'harmonic'):mode)),skillInfo(skill).title)})}
function saveActive(){if(!quiz||quiz.finished)return;db.active=structuredClone(quiz);save()}
function resume(){quiz=structuredClone(db.active);quiz.level=quiz.level||db.level;quiz.started=Date.now();view='quiz';showMap=false;render()}
function fingerprint(q){return [q.skill,q.type,q.title,q.feature||'',q.glyph||'',q.dot||false,q.meter?.join('/')||'',q.key??'',q.notes.map(n=>`${n.d}:${n.acc}`).join(','),q.correct,q.mode,JSON.stringify(q.rhythm||[]),q.boundary||'',q.missingFrom??'',JSON.stringify(q.optionRhythms||{})].join('|')}
function check(){const a=quiz.answers[quiz.index],q=quiz.questions[quiz.index];if(!a||a.checked)return;a.checked=true;a.correct=a.choice===q.correct;db.attempts.push({skill:q.skill,correct:a.correct,date:Date.now()});db.attempts=db.attempts.slice(-1000);if(a.correct)db.wrong=db.wrong.filter(x=>fingerprint(x)!==fingerprint(q));else if(!db.wrong.some(x=>fingerprint(x)===fingerprint(q)))db.wrong.push(structuredClone(q));db.wrong=db.wrong.slice(-200);saveActive();render();app.querySelector('.feedback')?.scrollIntoView({block:'start'})}
function questionPage(){const q=quiz.questions[quiz.index],a=quiz.answers[quiz.index],checked=a?.checked;return `<header class="back-head quiz-header"><button class="icon-button back" data-act="pause" aria-label="保存并返回">${icon('back')}</button><h2>${quiz.label}</h2><button class="question-count" data-act="map" aria-label="题目导航 ${quiz.index+1}/${quiz.questions.length}">${quiz.index+1}/${quiz.questions.length}</button></header><div class="progress"><i style="width:${(quiz.index+1)/quiz.questions.length*100}%"></i></div>${showMap?`<section class="question-navigation"><div class="map">${quiz.questions.map((_,i)=>`<button data-act="jump" data-index="${i}" class="${i===quiz.index?'current ':''}${quiz.answers[i]?.checked?quiz.answers[i].correct?'ok':'bad':''}">${i+1}</button>`).join('')}</div><button class="textbtn" data-act="end">结束练习</button></section>`:''}<article class="q-card"><h1>${q.title}</h1><p class="question-hint">单选</p>${q.sequence?audioControls():''}${q.type==='ear'?`<div class="listen"><button class="play" data-act="play-q" data-audio-play aria-label="播放题目音频">${icon('play')}</button><div class="waveform" aria-hidden="true">${[9,15,25,18,34,47,29,18,34,58,43,25,17,30,45,62,38,24,14,28,42,32,18,23,13,8].map((h,i)=>`<i style="--height:${h}px;--delay:${i*-.06}s"></i>`).join('')}</div><p class="audio-state" data-audio-status aria-live="polite"></p></div>`:q.optionScores&&q.hideNotes?'':notation(q,{id:'question-staff'})}<div class="option-grid">${q.options.map((t,i)=>`<button class="option ${q.optionScores||q.optionRhythms?'score-option ':''}${a?.choice===t?'selected ':''}${checked&&t===q.correct?'correct ':''}${checked&&a.choice===t&&!a.correct?'wrong':''}" data-act="choose" data-choice="${i}" aria-pressed="${a?.choice===t}" ${checked?'disabled':''}>${optionMarkup(q,t)}${q.optionScores||q.optionRhythms?`<span class="option-indicator" aria-hidden="true">${checked&&t===q.correct?icon('check'):''}</span>`:checked&&t===q.correct?icon('check'):''}</button>`).join('')}</div>${checked?`<section class="feedback ${a.correct?'good':'bad'}"><strong>${a.correct?'答对了':'正确答案：'+q.correct}</strong>${!a.correct&&briefFeedback(q,a.choice)?`<p class="feedback-reason">${briefFeedback(q,a.choice)}</p>`:''}${answerAudio(q)}<details class="answer-explanation"><summary>查看解析</summary><div class="answer-detail">${explanation(q)}${q.type==='ear'?(q.skill.startsWith('b-')?notation(q,{reveal:true,id:'answer-staff'}):staff(q.notes,{label:true,harmonic:q.mode==='harmonic',id:'answer-staff'})):''}${(q.showAfterOnly||q.hideNotes||q.boundary||q.missingFrom!==undefined)?notation(q,{reveal:true,id:'revealed-concept'}):''}${q.type==='invert'?staff([q.notes[1],note(q.notes[0].d+7,q.notes[0].acc)],{label:true,id:'inversion-result'}):''}<div class="explanation-actions"><button class="textbtn" data-act="related">对应讲解 ${icon('chevron')}</button></div></div></details></section>`:''}</article><div class="quiz-action">${checked?`<button class="primary" data-act="next">${quiz.index===quiz.questions.length-1?'完成练习':'下一题'}</button>`:`<button class="primary" data-act="check" ${!a?'disabled':''}>检查答案</button>`}</div>`}
function pause(){piano.stop();pauseRunClock(quiz);saveActive();go('practice')}
function finish(){const incomplete=quiz.questions.length-Object.values(quiz.answers).filter(x=>x.checked).length;const done=()=>{piano.stop();pauseRunClock(quiz);quiz.finished=true;result=structuredClone(quiz);const correct=Object.values(quiz.answers).filter(x=>x.checked&&x.correct).length;db.sessions.push({level:quiz.level||db.level,label:quiz.label,date:Date.now(),correct,answered:Object.values(quiz.answers).filter(x=>x.checked).length,count:quiz.questions.length});db.sessions=db.sessions.slice(-60);for(const q of quiz.questions){if(quiz.answers[quiz.questions.indexOf(q)]?.checked&&!db.completedLessons.includes(q.skill))db.completedLessons.push(q.skill)}db.active=null;save();go('result')};if(incomplete)ask('现在结束练习？',`还有 ${incomplete} 题未检查。它们将显示为未完成，不会计入作答正确率。`,done);else done()}
function resultPage(){if(!result)return '';const a=Object.values(result.answers).filter(x=>x.checked),ok=a.filter(x=>x.correct).length,unfinished=result.questions.length-a.length;const misses=[...new Set(result.questions.filter((q,i)=>result.answers[i]?.checked&&!result.answers[i].correct).map(q=>q.skill))];return `${backHead('练习小结')}<section class="summary"><h1>练习完成</h1><div class="ring">${ok}<small>/ ${a.length} 道已答题正确</small></div><p>${a.length?'已答题正确率 '+Math.round(ok/a.length*100)+'%':'尚未检查答案'} · ${Math.floor(result.elapsed/60000)}分${Math.floor(result.elapsed/1000)%60}秒${unfinished?`<br>${unfinished}题未完成`:''}</p><div class="bottom-actions"><button class="secondary" data-act="go" data-view="home">回到学习</button><button class="primary" data-act="${misses.length?'result-wrong':'again'}">${misses.length?'巩固本次错题':'再练一组'}</button></div></section>${misses.length?`<div class="section-head"><h2>建议回看的知识点</h2></div>${misses.map(id=>`<button class="list-row" data-act="lesson" data-skill="${id}"><b>${skillInfo(id).title}</b><span>看讲解 →</span></button>`).join('')}`:''}<div class="section-head"><h2>逐题回顾</h2></div>${result.questions.map((q,i)=>{const a=result.answers[i];return `<details class="card"><summary style="cursor:pointer;font-size:14px">第${i+1}题 · ${skillInfo(q.skill).title} <span style="float:right">${!a?.checked?'未完成':a.correct?'✓ 正确':'待巩固'}</span></summary><div style="margin-top:15px">${notation(q,{reveal:true,id:'review-'+i})}<div class="tiny">你的选择：${a?.choice||'未选择'} · 正确答案：${q.correct}</div><p>${explanation(q)}</p>${q.sequence?audioControls():''}${answerAudio(q,i)}</div></details>`}).join('')}`}
function ask(title,body,fn){let dialog=document.createElement('dialog');dialog.innerHTML=`<h3>${title}</h3><p>${body}</p><div class="bottom-actions"><button class="secondary" data-cancel>取消</button><button class="primary" data-confirm>确认</button></div>`;document.body.append(dialog);dialog.querySelector('[data-cancel]').onclick=()=>{dialog.close();dialog.remove()};dialog.querySelector('[data-confirm]').onclick=()=>{dialog.close();dialog.remove();fn()};dialog.addEventListener('cancel',()=>dialog.remove());dialog.showModal()}
let relatedReturn=false;
app.addEventListener('toggle',e=>{
 const chapter=e.target;if(chapter.matches?.('.practice-options')&&app.contains(chapter)){practiceOptionsOpen=chapter.open;return}if(!chapter.matches?.('details[data-chapter]')||!app.contains(chapter))return;
 if(chapter.open){openChapters[db.level]=chapter.dataset.chapter;app.querySelectorAll('details[data-chapter][open]').forEach(other=>{if(other!==chapter)other.open=false})}
 else if(openChapters[db.level]===chapter.dataset.chapter)openChapters[db.level]='';
},true);
app.addEventListener('pointerdown',()=>piano.unlock(),{capture:true});
app.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' ')piano.unlock()},{capture:true});
app.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el||el.disabled)return;const a=el.dataset.act;switch(a){case 'level':{piano.stop();if(quiz&&!quiz.finished){pauseRunClock(quiz);saveActive()}db.level=el.dataset.level;GROUPS=groupsFor(db.level);group=GROUPS[0].id;skill=GROUPS[0].skills[0];quiz=null;save();render();break}case 'record-filter':recordFilter=el.dataset.filter;render();break;case 'module':group=el.dataset.group;go('module');break;case 'practice-group':group=el.dataset.group;selectPracticeSkill(GROUPS.find(g=>g.id===group).skills[0]);render();break;case 'select-practice':selectPracticeSkill(el.dataset.skill);render();break;case 'practice-wrong':recordFilter=db.level;wrongReturn='practice';go('wrong');break;case 'result-wrong':{const questions=missedQuestions(result);if(questions.length)replaceActive(()=>makeRun(structuredClone(questions),'本次错题巩固','wrong'));break;}case 'group-practice':group=el.dataset.group;go('practice');break;case 'module-mixed':{const g=GROUPS.find(x=>x.id===el.dataset.group);replaceActive(()=>{const seed=Math.floor(Math.random()*1e9);makeRun(Array.from({length:10},(_,i)=>makeQuestion(g.skills[i%g.skills.length],i,seed,'basic','up')),g.title+'综合练习','mixed','basic')});break}case 'go':relatedReturn=false;if(el.dataset.view==='wrong')wrongReturn=view==='practice'?'practice':'mine';go(el.dataset.view);break;case 'lesson':skill=el.dataset.skill;group=groupFor(skill).id;relatedReturn=false;go('lesson');break;case 'configure':selectPracticeSkill(el.dataset.skill);group=groupFor(skill).id;go('configure');break;case 'difficulty':difficulty=el.dataset.value;savePracticePreferences();render();break;case 'mode':mode=el.dataset.value;savePracticePreferences();render();break;case 'count':count=Number(el.dataset.value);savePracticePreferences();render();break;case 'start':start();break;case 'resume':resume();break;case 'demo':{const played=el.dataset.sequence?piano.playSequence(JSON.parse(decodeURIComponent(el.dataset.sequence)),db.settings.bpm||80,2):piano.play(el.dataset.notes.split(',').map(Number),el.dataset.mode||'up');if(played)highlightPlayback(el);break;}case 'play-q':playQuestion(quiz.questions[quiz.index],undefined,el);break;case 'answer-audio':playQuestion(questionForButton(el),el.dataset.mode||undefined,el);break;case 'chord-arpeggio':playQuestion(quiz.questions[quiz.index],'up',el);break;case 'choose':{const i=quiz.index;if(quiz.answers[i]?.checked)break;quiz.answers[i]={choice:quiz.questions[i].options[Number(el.dataset.choice)],checked:false};saveActive();render();break}case 'check':piano.stop();check();break;case 'previous':piano.stop();quiz.index--;saveActive();render();window.scrollTo(0,0);break;case 'next':if(quiz.index<quiz.questions.length-1){piano.stop();quiz.index++;saveActive();render();window.scrollTo(0,0)}else finish();break;case 'jump':piano.stop();quiz.index=Number(el.dataset.index);saveActive();render();break;case 'map':showMap=!showMap;render();break;case 'pause':pause();break;case 'end':finish();break;case 'related':pauseRunClock(quiz);saveActive();skill=quiz.questions[quiz.index].skill;relatedReturn=true;piano.stop();view='lesson';render();app.querySelector('.back').dataset.act='return-quiz';app.querySelector('.bottom-actions').innerHTML='<button class="primary" data-act="return-quiz">返回当前练习 →</button>';break;case 'return-quiz':relatedReturn=false;resumeRunClock(quiz);saveActive();view='quiz';render();window.scrollTo(0,0);break;case 'start-mixed':replaceActive(()=>{const seed=Math.floor(Math.random()*1e9);makeRun(shuffle(GROUPS.flatMap(g=>Array.from({length:3},(_,i)=>makeQuestion(shuffle(g.skills)[i%g.skills.length],i+GROUPS.indexOf(g)*3,seed,'basic','up')))),levelTitle()+'综合练习','mixed','basic')});break;case 'reinforce-wrong':{if(!scopedWrong().length){toast('当前没有待巩固错题');break}replaceActive(()=>{const seed=Math.floor(Math.random()*1e9),src=scopedWrong().slice();makeRun(Array.from({length:5},(_,i)=>makeQuestion(src[i%src.length].skill,i,seed,'varied',src[i%src.length].mode)),'同类补练','practice')});break}case 'start-wrong':if(!scopedWrong().length){toast('当前没有待巩固错题');break}replaceActive(()=>makeRun(structuredClone(scopedWrong().slice(0,15)),'错题巩固','wrong'));break;case 'wrong-one':replaceActive(()=>makeRun([structuredClone(db.wrong[Number(el.dataset.index)])],'错题巩固','wrong'));break;case 'again':{const old=result;replaceActive(()=>{const seed=Math.floor(Math.random()*1e9);makeRun(old.questions.map((q,i)=>makeQuestion(q.skill,i,seed,old.difficulty||'basic',q.mode)),old.label,'practice',old.difficulty||'basic')});break}case 'review-audio':{const q=result.questions[Number(el.dataset.index)];playQuestion(q,undefined,el);break}}});
app.addEventListener('input',e=>{const key=e.target.dataset.setting;if(key){db.settings[key]=Number(e.target.value);if(key!=='bpm')piano[key]=db.settings[key];else piano.stop();const v=document.querySelector('#volume-value');if(v)v.textContent=Math.round(db.settings.volume*100)+'%';save()}});
window.addEventListener('pagehide',()=>{piano.stop();if(quiz&&!quiz.finished&&view==='quiz'){pauseRunClock(quiz);saveActive()}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)piano.stop();if(quiz&&!quiz.finished&&view==='quiz'){if(document.hidden)pauseRunClock(quiz);else resumeRunClock(quiz);saveActive()}});
window.addEventListener('pageshow',()=>{if(quiz&&!quiz.finished&&view==='quiz'&&!document.hidden){resumeRunClock(quiz);saveActive()}});render();
piano.preload();
